\section{Introduction}

\subsection{Two Lorentzian geometries}

A Pythagorean triple $(a,b,c)$ with $a^2+b^2=c^2$ is an integral null vector for the
quadratic form $Q(a,b,c)=a^2+b^2-c^2$ of signature $(2,1)$.  Write $\Lor$ for $\ZZ^3$ with
\[
  \ip{(a,b,c)}{(a',b',c')} = aa'+bb'-cc', \qquad Q(v)=\ip{v}{v}.
\]
The primitive Pythagorean triples with positive entries are exactly the primitive
future-pointing null vectors of $\Lor$ in the positive octant.

Barning (1963), and independently Hall and later Berggren, discovered that this set carries
a free ternary tree structure.  The matrices
\[
A=\begin{pmatrix}1&-2&2\\ 2&-1&2\\ 2&-2&3\end{pmatrix},\quad
B=\begin{pmatrix}1&2&2\\ 2&1&2\\ 2&2&3\end{pmatrix},\quad
C=\begin{pmatrix}-1&2&2\\ -2&1&2\\ -2&2&3\end{pmatrix}
\]
are integral isometries of $Q$, and the orbit of the root $\rho_0=(3,4,5)$ under the free
monoid they generate enumerates every primitive triple exactly once.  A word
$g\in\{A,B,C\}^{*}$ is a \emph{Berggren address}; $N(g)=g\cdot\rho_0$ is the corresponding
\emph{node}.  Freeness on the root --- distinct addresses give distinct nodes --- is the
completeness-and-uniqueness statement of the tree, used throughout.

On the other side stands $\mathrm{II}(25,1)$, the unique even unimodular lattice of
signature $(25,1)$.  Conway's \emph{holy construction} takes the primitive isotropic Weyl
vector $w=(0,1,\dots,24;70)$ --- note $\sum_{k=0}^{24}k^2=4900=70^2$, so $Q(w)=0$ --- and
produces
\[
  w^{\perp}/\ZZ w \;\cong\; \Lambda,
\]
the Leech lattice: the unique rootless even unimodular lattice of rank $24$, of minimum
$4$.  Its $23$ classes of deep holes correspond to the $23$ Niemeier lattices with roots;
with $\Lambda$ itself there are $24$ Niemeier lattices.  One has $\Aut(\Lambda)=
\mathrm{Co}_0$; from $\Lambda$ one constructs the moonshine module, whose automorphism
group is the Monster $\Mon$ and whose graded dimensions reproduce
\[
  j(q)-744 = q^{-1}+196884\,q+21493760\,q^{2}+864299970\,q^{3}+\cdots,
\]
with $196884=196883+1$ and $21493760=21296876+196883+1$.

\subsection{The question and the answers}

Both geometries are integral, Lorentzian, and organised by the arithmetic of a null cone
acted on by a reflection group.  We ask:
\begin{enumerate}
  \item[(i)] does $\Lor$, hence the Berggren monoid, embed in $\mathrm{II}(25,1)$ and its
        automorphism group?
  \item[(ii)] do the tree's nodes and ternary branches match the deep-hole / Niemeier
        structure?
  \item[(iii)] does the moonshine head data acquire a tree-parametrised organisation?
\end{enumerate}
The answers established below: (i) no verbatim, yes and faithfully after doubling; (ii) no,
for airtight counting reasons; (iii) no, for a sharp arithmetic reason that also pins down
exactly what the tree's radial coordinate does see.  A positive theorem replaces the
conjecture: the Pythagorean null cone's holy construction is uniformly $A_1$.

\section{Definitions}

\begin{definition}[Lorentzian lattice of the Pythagorean form]
$\Lor$ is $\ZZ^3$ with $\ip{v}{w}=v_1w_1+v_2w_2-v_3w_3$ and $Q(v)=\ip{v}{v}$.  A vector
$v$ is \emph{isotropic} (null) if $Q(v)=0$, and \emph{primitive} if the only integers
dividing all three coordinates are units.
\end{definition}

\begin{definition}[Even lattice form]
An \emph{even lattice form} on an abelian group $M$ is a symmetric $\ZZ$-bilinear map
$\ipM{\cdot}{\cdot}:M\times M\to\ZZ$ with $\ipM{x}{x}\in 2\ZZ$ for every $x$.  No
nondegeneracy is assumed; none is needed below.  The Leech lattice, all Niemeier lattices
and $\mathrm{II}(25,1)$ are even in this sense.
\end{definition}

\begin{definition}[Root, root reflection]
A \emph{root} of an even lattice $M$ is $\rho$ with $\ipM{\rho}{\rho}=2$; its reflection is
$s_\rho(x)=x-\ipM{x}{\rho}\rho$, integral on all of $M$ because the norm is exactly $2$.
\end{definition}

\begin{definition}[Unit reflection in $\Lor$]
For $r\in\Lor$ with $Q(r)=1$, put $\su{r}(x)=x-2\ip{x}{r}\,r$; again no denominator
appears.
\end{definition}

\begin{definition}[Doubling]
$\Lor(2)$ denotes $\ZZ^3$ with the form $2\ip{\cdot}{\cdot}$.  It is even, isomorphic to
$A_1\oplus A_1\oplus\langle -2\rangle$, with the coordinate vectors as an orthogonal frame
of norms $(2,2,-2)$.
\end{definition}

\begin{definition}[$(2,2,-2)$-frame]
A \emph{frame} in an even lattice $M$ is a triple $(u_1,u_2,w)$ of pairwise orthogonal
vectors with $\ipM{u_1}{u_1}=\ipM{u_2}{u_2}=2$ and $\ipM{w}{w}=-2$.
\end{definition}

\begin{definition}[Hypotenuse; levels and balls]
For an address $g$, the hypotenuse is $h(g)=N(g)_3$.  The level of depth $n$ has $3^n$
addresses; the ball of radius $n$ has $\beta_n=\sum_{k\le n}3^k=(3^{n+1}-1)/2 =
1,4,13,40,121,\dots$ addresses.
\end{definition}

\section{The Barning--Hall generators are reflection words}

\begin{lemma}\label{lem:unitrefl}
Let $r\in\Lor$ with $Q(r)=1$.  Then $\ip{\su{r}x}{\su{r}y}=\ip{x}{y}$ for all $x,y$, and
$\su{r}\circ\su{r}=\mathrm{id}$.  In particular $\su{r}$ preserves $Q$ and maps the null
cone to itself.
\end{lemma}

\begin{proof}[Proof sketch]
Expanding, $\ip{\su{r}x}{\su{r}y}-\ip{x}{y}=4\ip{x}{r}\ip{y}{r}\bigl(Q(r)-1\bigr)=0$.
Involutivity follows from $\ip{\su{r}x}{r}=\ip{x}{r}-2\ip{x}{r}Q(r)=-\ip{x}{r}$.
\end{proof}

\begin{theorem}[Reflection decomposition]\label{thm:decomp}
Put
\[
  e_1=(1,0,0),\quad e_2=(0,1,0),\quad \alpha=(1,-1,-1),\quad \beta=(1,1,-1),\quad
  \gamma=(-1,1,-1),
\]
each of norm $Q=1$.  Then, as maps on $\Lor$,
\[
  A=\su{e_1}\circ\su{\alpha},\qquad C=\su{e_2}\circ\su{\gamma},\qquad
  B=\su{e_1}\circ\su{e_2}\circ\su{\beta}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Each identity compares two integer-linear maps on $\ZZ^3$, i.e.\ nine polynomial
identities in the coordinates $(a,b,c)$, all verified by expansion.  For instance the
first coordinate of $\su{e_1}\su{\alpha}(a,b,c)$ is $a-2b+2c$, the first row of $A$.
\end{proof}

The parity of the number of reflections is forced: $\det A=\det C=+1$ (two reflections)
while $\det B=-1$, so $B$ needs an odd number and two do not suffice.

\begin{corollary}[Every node is a unit-reflection word]\label{cor:reflword}
For every address $g$ there is a list $R(g)=(r_1,\dots,r_k)$ of unit-norm vectors with
$g\cdot v=\su{r_1}\cdots\su{r_k}(v)$ for all $v$, and
\[
  k=|R(g)|=3\,\#_B(g)+2\,\#_{A,C}(g).
\]
Thus the Berggren monoid lies inside the reflection group of the \emph{odd} lattice $\Lor$.
\end{corollary}

\begin{proposition}\label{prop:odd}
All five vectors $e_1,e_2,\alpha,\beta,\gamma$ have \emph{odd} norm $1$.
\end{proposition}

\section{Parity obstruction and the doubled embedding}

\subsection{The obstruction}

\begin{theorem}[No isometric map into an even lattice]\label{thm:parity}
Let $M$ carry an even lattice form.  There is \emph{no} function $f:\Lor\to M$ --- not
required to be linear, injective, or structured in any way --- with
\[
  \ipM{f(v)}{f(w)}=\ip{v}{w}\qquad\text{for all }v,w\in\Lor .
\]
In particular the Pythagorean Lorentzian lattice does not embed isometrically into
$\mathrm{II}(25,1)$, into the Leech lattice, or into any Niemeier lattice.
\end{theorem}

\begin{proof}
If $f$ existed then $\ipM{f(e_1)}{f(e_1)}=\ip{e_1}{e_1}=1$, odd, contradicting evenness.
\end{proof}

\begin{remark}
The hypothesis is used at the single pair $(e_1,e_1)$, so the theorem is as strong as
possible.  The obstruction is not about dimension, discriminant or signature --- all of
which are compatible, since $\mathrm{II}(25,1)$ contains Lorentzian sublattices of rank
$3$ in abundance.  It is purely about parity.
\end{remark}

\subsection{The repair}

\begin{lemma}
The rescaled form $2\ip{\cdot}{\cdot}$ on $\ZZ^3$ is an even lattice form, and
$\Lor(2)\cong A_1\oplus A_1\oplus\langle-2\rangle$.
\end{lemma}

\begin{theorem}[Frame embedding]\label{thm:frame}
Let $M$ be an even lattice with a frame $F=(u_1,u_2,w)$ of norms $(2,2,-2)$.  Define
\[
  \varepsilon_F:\ZZ^3\to M,\qquad \varepsilon_F(a,b,c)=au_1+bu_2+cw .
\]
Then $\varepsilon_F$ is additive, $\ZZ$-homogeneous, injective, and
\[
  \ipM{\varepsilon_F(v)}{\varepsilon_F(v')}=2\,\ip{v}{v'} \qquad\text{for all }v,v'.
\]
Consequently $\varepsilon_F$ is an isometry of $\Lor(2)$ onto its image, and any $r$ with
$Q(r)=1$ maps to a \emph{root}: $\ipM{\varepsilon_F(r)}{\varepsilon_F(r)}=2$.
\end{theorem}

\begin{proof}[Proof sketch]
Bilinearity and the frame relations give $\ipM{\varepsilon_Fv}{\varepsilon_Fv'}=
2aa'+2bb'-2cc'$.  For injectivity, pair $\varepsilon_Fv=\varepsilon_Fv'$ against
$\varepsilon_Fe_1,\varepsilon_Fe_2,\varepsilon_Fe_3$ and read off $2a=2a'$, $2b=2b'$,
$-2c=-2c'$.
\end{proof}

\begin{definition}
For an address $g$ with reflection list $R(g)=(r_1,\dots,r_k)$, set
\[
  \Phi_F(g)=s_{\varepsilon_F(r_1)}\circ\cdots\circ s_{\varepsilon_F(r_k)}:M\to M,
\]
a composite of root reflections of $M$, integral on all of $M$, with no splitting of $M$
required.
\end{definition}

\begin{theorem}[Faithful embedding after doubling]\label{thm:faithful}
Let $M$ be an even lattice with a $(2,2,-2)$-frame $F$.  Then:
\begin{enumerate}
  \item $\Phi_F(gg')=\Phi_F(g)\circ\Phi_F(g')$ and $\Phi_F(\varnothing)=\mathrm{id}$, so
        $\Phi_F$ is a monoid homomorphism from the free monoid on $\{A,B,C\}$;
  \item $\ipM{\Phi_F(g)x}{\Phi_F(g)y}=\ipM{x}{y}$ for all $x,y\in M$;
  \item each $\Phi_F(g)$ is bijective, so $\Phi_F$ lands in $\Aut(M)$;
  \item $\Phi_F(g)\bigl(\varepsilon_F(v)\bigr)=\varepsilon_F(g\cdot v)$ for all $v\in\Lor$;
  \item $\Phi_F$ is \emph{injective}: distinct Berggren addresses give distinct
        automorphisms of $M$.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
(1) is concatenation of reflection lists.  (2) uses Theorem~\ref{thm:frame} and
$\ipM{s_\rho x}{s_\rho y}=\ipM{x}{y}-2\ipM{x}{\rho}\ipM{y}{\rho}+
\ipM{x}{\rho}\ipM{y}{\rho}\ipM{\rho}{\rho}=\ipM{x}{y}$ when $\ipM{\rho}{\rho}=2$.
(3) each root reflection is an involution, hence bijective.  (4) follows by induction
along $R(g)$ from the intertwining identity
\[
  s_{\varepsilon_F(r)}\bigl(\varepsilon_F(x)\bigr)=\varepsilon_F\bigl(\su{r}(x)\bigr)
  \qquad (Q(r)=1),
\]
valid because $\su{r}(x)=x-(2\ip{x}{r})r$ while $\ipM{\varepsilon_Fx}{\varepsilon_Fr}=
2\ip{x}{r}$: the doubling supplies exactly the factor $2$ of the unit reflection.
(5) if $\Phi_F(g)=\Phi_F(g')$, apply both to $\varepsilon_F(3,4,5)$, use (4) and
injectivity of $\varepsilon_F$ to get $g\cdot(3,4,5)=g'\cdot(3,4,5)$, and conclude $g=g'$
by freeness of the tree.
\end{proof}

\begin{corollary}[Non-vacuity]
A $(2,2,-2)$-frame exists in $\Lor(2)$ itself, and in $\mathrm{II}(25,1)$, which contains
$A_1\oplus A_1\oplus\langle-2\rangle$.  Hence the Berggren monoid embeds faithfully in the
isometry group of an even Lorentzian lattice, in particular in $\Aut(\mathrm{II}(25,1))$.
\end{corollary}

Part~(i) of the moonshot is thus refuted verbatim by Theorem~\ref{thm:parity} and
re-established, with faithfulness, by Theorem~\ref{thm:faithful} after the canonical
rescaling.  The factor $2$ measures exactly the discrepancy between the odd Barning--Hall
reflection vectors and the even roots of moonshine lattices, and by
Theorem~\ref{thm:parity} there is no way around it.

\section{Counting obstructions to a deep-hole correspondence}

\begin{theorem}[Levels]
For all $n\ge 0$: $3^n\ne 23$ and $3^n\ne 24$.
\end{theorem}

\begin{proof}
If $3^n=23$ then $n\ge1$, so $3\mid 23$, false.  If $3^n=24$ then $2\mid 3^n$, so $2\mid3$,
false.
\end{proof}

\begin{theorem}[Balls]
For all $n\ge 0$: $\beta_n\ne 23$ and $\beta_n\ne 24$.
\end{theorem}

\begin{proof}
$\beta_0,\dots,\beta_3=1,4,13,40$, and $\beta_n\ge\beta_4=121>24$ for $n\ge4$ by
monotonicity.
\end{proof}

\begin{theorem}[No injective Niemeier labelling]\label{thm:label}
The set of Berggren addresses is infinite.  Hence every map $f$ from addresses to the $24$
Niemeier classes is non-injective, and some class has infinite fibre.
\end{theorem}

\begin{proof}
The addresses $A^n$, $n\in\NN$, are pairwise distinct; a map from an infinite set to a
finite set is non-injective, and by the infinite pigeonhole principle some fibre is
infinite.
\end{proof}

\begin{theorem}[Transfer to triples]
For every labelling $f$ of Pythagorean triples by the $24$ Niemeier classes there is a
class $i$ such that infinitely many distinct \emph{nodes} carry label $i$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:label} to $g\mapsto f(N(g))$ to obtain an infinite set $S$ of
addresses with common label; $g\mapsto N(g)$ is injective by freeness, so $N(S)$ is
infinite.
\end{proof}

Hypothesis (ii) therefore fails.  What survives is only that a Niemeier labelling is a
finite colouring of an infinite tree, with an infinite monochromatic fibre.

\section{The radial coordinate: Gaussian-split law and prime spectrum}

Every primitive Pythagorean triple has the Euclid parametrisation
$(m^2-n^2,\,2mn,\,m^2+n^2)$ with $m>n>0$, $\gcd(m,n)=1$ and $m-n$ odd, so every node
hypotenuse is a sum of two \emph{coprime} squares.

\begin{theorem}[Congruence law]
For every address $g$, $h(g)\equiv 1 \pmod 4$.
\end{theorem}

\begin{proof}[Proof sketch]
With $m,n$ of opposite parity, write the even one as $2k$ and the odd one as $2l\pm1$;
then $m^2+n^2=4(\cdots)+1$.
\end{proof}

\begin{theorem}[Gaussian-split law]\label{thm:split}
Let $p$ be a prime with $p\equiv 3\pmod 4$.  Then $p\nmid h(g)$ for every address $g$.
Equivalently, node hypotenuses are products of primes that split in $\ZZ[i]$.
\end{theorem}

\begin{proof}
Write $h(g)=m^2+n^2$ with $\gcd(m,n)=1$ and suppose $p\mid m^2+n^2$.  In $\FF_p$: if
$n\equiv0$ then $m^2\equiv 0$, so $p\mid m$ and $p\mid n$, contradicting coprimality via
B\'ezout.  So $n$ is invertible and $(mn^{-1})^2\equiv-1$, i.e.\ $-1$ is a square mod $p$.
But $-1$ is a quadratic residue modulo an odd prime $p$ exactly when $p\equiv 1\pmod 4$.
\end{proof}

\begin{corollary}[Exclusion criterion]\label{cor:excl}
If some prime $p\equiv3\pmod4$ divides $N$, then $N$ is not the hypotenuse of any node.
\end{corollary}

\begin{theorem}[The moonshine head data is excluded]
None of $196883$, $196884$, $21296876$, $21493760$, $23$, $24$ is the hypotenuse of a node.
\end{theorem}

\begin{proof}
Apply Corollary~\ref{cor:excl} with the obstructing primes listed in Table~\ref{tab:head}.
\end{proof}

