"""Certificates: the parity obstruction, the doubled embedding, and the
exclusion of the moonshine head data.

This focused demonstration produces, for each of the three main negative
results and the one positive result, an explicit numerical certificate that can
be checked by hand:

  (1) a vector of the Pythagorean Lorentzian lattice of odd norm, which no even
      lattice can contain -- refuting an isometric copy inside II(25,1);
  (2) the abstract even lattice A_1 + A_1 + <-2> with its (2,2,-2) frame, and a
      table showing that each Barning-Hall generator acts on it as a product of
      root reflections, faithfully;
  (3) for each moonshine constant, the obstructing prime = 3 (mod 4) together
      with the full factorisation;
  (4) for a sample of nodes, the holy-construction data (sigma, tau) with the
      Lagrange certificate Q(tau) = <rho,sigma>^2 - Q(rho) Q(sigma) = 1.
"""

from __future__ import annotations

from itertools import product
from math import gcd
from typing import Dict, List, Tuple

Vec = Tuple[int, int, int]
Mat = Tuple[Vec, Vec, Vec]

GENS: Dict[str, Mat] = {
    "A": ((1, -2, 2), (2, -1, 2), (2, -2, 3)),
    "B": ((1, 2, 2), (2, 1, 2), (2, 2, 3)),
    "C": ((-1, 2, 2), (-2, 1, 2), (-2, 2, 3)),
}
ROOT: Vec = (3, 4, 5)
REFL: Dict[str, List[Vec]] = {
    "A": [(1, 0, 0), (1, -1, -1)],
    "B": [(1, 0, 0), (0, 1, 0), (1, 1, -1)],
    "C": [(0, 1, 0), (-1, 1, -1)],
}


def bil(v: Vec, w: Vec) -> int:
    return v[0] * w[0] + v[1] * w[1] - v[2] * w[2]


def apply_mat(m: Mat, v: Vec) -> Vec:
    return tuple(sum(m[i][j] * v[j] for j in range(3)) for i in range(3))  # type: ignore


def word(addr: str, v: Vec = ROOT) -> Vec:
    out = v
    for ch in addr:
        out = apply_mat(GENS[ch], out)
    return out


def root_reflection(rho: Vec, x: Vec) -> Vec:
    """In the even lattice Z^{2,1}(2): s_rho(x) = x - <x,rho>_2 rho."""
    t = 2 * bil(x, rho)
    return (x[0] - t * rho[0], x[1] - t * rho[1], x[2] - t * rho[2])


def aut(addr: str, x: Vec) -> Vec:
    rs = [r for ch in reversed(addr) for r in REFL[ch]]
    out = x
    for r in reversed(rs):
        out = root_reflection(r, out)
    return out


def factors(n: int) -> List[int]:
    out, d, m = [], 2, abs(n)
    while d * d <= m:
        while m % d == 0:
            out.append(d)
            m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def extgcd(a: int, b: int) -> Tuple[int, int, int]:
    if b == 0:
        return (abs(a), 1 if a >= 0 else -1, 0)
    g, x, y = extgcd(b, a % b)
    return (g, y, x - (a // b) * y)


def pairing_one(rho: Vec) -> Vec:
    a, b, c = rho
    g1, x, y = extgcd(a, b)
    _, u, v = extgcd(g1, c)
    return (x * u, y * u, -v)


def lor_cross(v: Vec, w: Vec) -> Vec:
    return (v[1] * w[2] - v[2] * w[1],
            v[2] * w[0] - v[0] * w[2],
            v[1] * w[0] - v[0] * w[1])


def certificate_1() -> None:
    print("(1) PARITY CERTIFICATE")
    e1: Vec = (1, 0, 0)
    print(f"    Q(e1) = <{e1},{e1}> = {bil(e1, e1)}, which is odd.")
    print("    Every vector of an even lattice has even norm, so no form-preserving")
    print("    map (of any kind) into II(25,1), Leech, or a Niemeier lattice exists.")
    print(f"    Doubled: 2*Q(e1) = {2 * bil(e1, e1)} -- a ROOT, exactly what is needed.")


def certificate_2() -> None:
    print("\n(2) DOUBLED-EMBEDDING CERTIFICATE  (model lattice A_1 + A_1 + <-2>)")
    frame = {"u1": (1, 0, 0), "u2": (0, 1, 0), "w": (0, 0, 1)}
    for name, v in frame.items():
        print(f"    frame vector {name} = {v}: doubled norm {2 * bil(v, v):>3}")
    pairs = [("u1", "u2"), ("u1", "w"), ("u2", "w")]
    print("    orthogonality: " + ", ".join(
        f"<{a},{b}> = {2 * bil(frame[a], frame[b])}" for a, b in pairs))
    print("    the reflection action agrees with the Barning-Hall action:")
    probes: List[Vec] = [(3, 4, 5), (5, 12, 13), (2, 1, 2), (1, 0, 0)]
    for addr in ["A", "B", "C", "BCA", "ABCBA"]:
        ok = all(aut(addr, v) == word(addr, v) for v in probes)
        isom = all(2 * bil(aut(addr, v), aut(addr, u)) == 2 * bil(v, u)
                   for v in probes for u in probes)
        print(f"      {addr:<6} intertwines: {ok}   isometry: {isom}")
    seen = {word(a) for d in range(6)
            for a in ("".join(t) for t in product("ABC", repeat=d))}
    total = sum(3 ** d for d in range(6))
    print(f"    faithfulness: {total} addresses of depth <= 5 give {len(seen)} "
          f"distinct nodes")


def certificate_3() -> None:
    print("\n(3) EXCLUSION CERTIFICATES FOR THE MOONSHINE HEAD DATA")
    data = [(196883, "smallest faithful Monster representation"),
            (196884, "coefficient of q in j"),
            (21296876, "second Monster head dimension"),
            (21493760, "coefficient of q^2 in j"),
            (23, "deep-hole classes of the Leech lattice"),
            (24, "Niemeier lattices")]
    for n, label in data:
        fs = factors(n)
        p = next(q for q in fs if q % 4 == 3)
        counts: Dict[int, int] = {}
        for q in fs:
            counts[q] = counts.get(q, 0) + 1
        pretty = " * ".join(f"{q}^{e}" if e > 1 else str(q) for q, e in sorted(counts.items()))
        print(f"    {n:>9} = {pretty}")
        print(f"              blocked by {p} = 3 (mod 4)   [{label}]")


def certificate_4() -> None:
    print("\n(4) HOLY-CONSTRUCTION CERTIFICATES (Lagrange identity)")
    for addr in ["", "A", "B", "C", "AB", "CBA"]:
        rho = word(addr)
        sigma = pairing_one(rho)
        tau = lor_cross(rho, sigma)
        lhs = bil(tau, tau)
        rhs = bil(rho, sigma) ** 2 - bil(rho, rho) * bil(sigma, sigma)
        print(f"    node {str(rho):<18} sigma {str(sigma):<18} tau {str(tau):<22}")
        print(f"         <tau,rho> = {bil(tau, rho)},  Q(tau) = {lhs} = "
              f"<rho,sigma>^2 - Q(rho)Q(sigma) = {rhs}")
    print("    In every case the quotient is <1>, i.e. A_1 after doubling:")
    print("    it contains a root, whereas the Leech lattice has minimum 4.")


def main() -> None:
    print(__doc__)
    certificate_1()
    certificate_2()
    certificate_3()
    certificate_4()


if __name__ == "__main__":
    main()

