"""Algorithm: deciding the radial spectrum of the Berggren tree.

Decides whether a positive integer N can be the hypotenuse of a node, and, when
N is a prime = 1 (mod 4), constructs the node explicitly.

Mathematical basis.  Node hypotenuses are sums of two COPRIME squares, so
(a) they are = 1 (mod 4), and (b) no prime p = 3 (mod 4) divides them -- else
-1 would be a quadratic residue mod p.  Conversely, by Fermat's two-squares
theorem every prime p = 1 (mod 4) is a^2 + b^2 with a, b automatically coprime
and of opposite parity, hence an admissible Euclid parameter pair, so p occurs.
"""

from __future__ import annotations

from itertools import product
from math import gcd, isqrt
from typing import Dict, List, Optional, Tuple

Vec = Tuple[int, int, int]
Mat = Tuple[Vec, Vec, Vec]

GENS: Dict[str, Mat] = {
    "A": ((1, -2, 2), (2, -1, 2), (2, -2, 3)),
    "B": ((1, 2, 2), (2, 1, 2), (2, 2, 3)),
    "C": ((-1, 2, 2), (-2, 1, 2), (-2, 2, 3)),
}
ROOT: Vec = (3, 4, 5)


def prime_factors(n: int) -> List[int]:
    out: List[int] = []
    d, m = 2, n
    while d * d <= m:
        while m % d == 0:
            out.append(d)
            m //= d
        d += 1
    if m > 1:
        out.append(m)
    return out


def two_squares(p: int) -> Tuple[int, int]:
    """Write a prime p = 1 (mod 4) as a^2 + b^2 by direct search on a."""
    for a in range(1, isqrt(p) + 1):
        b2 = p - a * a
        b = isqrt(b2)
        if b * b == b2 and b > 0:
            return (max(a, b), min(a, b))
    raise ValueError(f"{p} is not a sum of two positive squares")


def euclid_triple(m: int, n: int) -> Vec:
    """Euclid's parametrisation (m^2 - n^2, 2mn, m^2 + n^2)."""
    return (m * m - n * n, 2 * m * n, m * m + n * n)


def locate_address(target: Vec, max_depth: int = 12) -> Optional[str]:
    """Find the Berggren address of a primitive triple by breadth-first search."""
    frontier: List[Tuple[Vec, str]] = [(ROOT, "")]
    for _ in range(max_depth + 1):
        nxt: List[Tuple[Vec, str]] = []
        for v, w in frontier:
            if v == target or (v[1], v[0], v[2]) == target:
                return w or "(root)"
            if v[2] > target[2]:
                continue
            for g, m in GENS.items():
                nxt.append((tuple(sum(m[i][j] * v[j] for j in range(3))  # type: ignore
                                  for i in range(3)), w + g))
        if not nxt:
            break
        frontier = nxt
    return None


def is_node_hypotenuse(n: int) -> Tuple[bool, str, Optional[str]]:
    """Decide membership in the radial spectrum.

    Returns (verdict, explanation, address-if-found).
    """
    if n < 1:
        return (False, "hypotenuses are positive", None)
    if n % 4 != 1:
        return (False, f"{n} is {n % 4} mod 4; every node hypotenuse is 1 mod 4", None)
    factors = prime_factors(n)
    bad = [p for p in factors if p % 4 == 3]
    if bad:
        return (False, f"the prime {bad[0]} = 3 (mod 4) divides {n} "
                       f"(Gaussian-split law)", None)
    if len(set(factors)) == 1 and len(factors) == 1:
        m, k = two_squares(n)
        triple = euclid_triple(m, k)
        return (True, f"{n} = {m}^2 + {k}^2, an admissible Euclid pair "
                      f"-> node {triple}", locate_address(triple))
    return (True, f"{n} passes the Gaussian-split law; every prime factor is "
                  f"1 mod 4, so {n} is a sum of two squares", None)


if __name__ == "__main__":
    for n in [5, 13, 17, 25, 29, 65, 23, 24, 196883, 196884, 21296876, 21493760]:
        verdict, why, addr = is_node_hypotenuse(n)
        flag = "YES" if verdict else "NO "
        extra = f"   address {addr}" if addr else ""
        print(f"{n:>9}  {flag}  {why}{extra}")
